export const ACTION_CHANGE_MARKER_KEY = "__action_change__";
export const ACTION_CHANGE_MARKER_ORG_PREFIX = "__org__:";
export function actionChangeDedupeKey(target, markerIdentity) {
    return `${markerIdentity}|${target.actionName ?? ""}|${target.owner ?? ""}|${target.orgId ?? ""}`;
}
export function actionChangeMarkerSession(target) {
    if (target.owner)
        return target.owner;
    if (target.orgId)
        return `${ACTION_CHANGE_MARKER_ORG_PREFIX}${target.orgId}`;
    return null;
}
export function actionChangeMarkerValue(target) {
    return {
        source: "action",
        ...(target.actionName ? { actionName: target.actionName } : {}),
        ...(target.owner ? { owner: target.owner } : {}),
        ...(target.orgId ? { orgId: target.orgId } : {}),
        ...(target.requestSource ? { requestSource: target.requestSource } : {}),
        ...(target.nonce ? { nonce: target.nonce } : {}),
    };
}
export function parseActionChangeMarker(sessionId, value) {
    let parsed = value;
    if (typeof value === "string") {
        try {
            parsed = JSON.parse(value);
        }
        catch {
            parsed = null;
        }
    }
    let actionName;
    let owner;
    let orgId;
    let requestSource;
    let nonce;
    if (parsed && typeof parsed === "object") {
        const record = parsed;
        actionName =
            typeof record.actionName === "string" ? record.actionName : undefined;
        owner = typeof record.owner === "string" ? record.owner : undefined;
        orgId = typeof record.orgId === "string" ? record.orgId : undefined;
        requestSource =
            typeof record.requestSource === "string"
                ? record.requestSource
                : undefined;
        nonce = typeof record.nonce === "string" ? record.nonce : undefined;
    }
    if (!owner && !orgId && typeof sessionId === "string" && sessionId) {
        if (sessionId.startsWith(ACTION_CHANGE_MARKER_ORG_PREFIX)) {
            const parsedOrgId = sessionId.slice(ACTION_CHANGE_MARKER_ORG_PREFIX.length);
            if (parsedOrgId)
                orgId = parsedOrgId;
        }
        else {
            owner = sessionId;
        }
    }
    if (!actionName && !owner && !orgId)
        return null;
    return {
        actionName,
        owner,
        orgId,
        requestSource,
        ...(nonce ? { nonce } : {}),
    };
}
